const RAW = 20000;
const points = (text, max) => {
  const out = [];
  for (const ch of text) {
    if (ch.length === 1 && ch.charCodeAt(0) >= 0xD800 && ch.charCodeAt(0) <= 0xDFFF) continue;
    out.push(ch);
    if (out.length > max) break;
  }
  return out;
};
const scrub = (text) => text
  .replace(/-----BEGIN [A-Z ]{0,40}PRIVATE KEY-----[\s\S]{0,8000}?(?:-----END [A-Z ]{0,40}PRIVATE KEY-----|$)/g, '[redacted]')
  .replace(/([A-Za-z0-9_.-]{0,64}(?:token|secret|password|passwd|pwd|api[_-]?key|apikey|authorization|cookie|credential|private[_-]?key|session)[A-Za-z0-9_.-]{0,64})(["']?[ \t]{0,5}[:=][ \t]{0,5})(?:"[^"\r\n]{0,2000}"?|'[^'\r\n]{0,2000}'?|[^\r\n]{0,2000})/gi, '$1$2[redacted]')
  .replace(/\b(bearer)[ \t]{1,5}[A-Za-z0-9._~+\/=-]{8,512}/gi, '$1 [redacted]')
  .replace(/\bbasic[ \t]{1,5}(?=[A-Za-z0-9+\/]{0,512}[0-9+\/=])[A-Za-z0-9+\/]{8,512}={0,2}/gi, 'Basic [redacted]')
  .replace(/\b([A-Za-z][A-Za-z0-9+.-]{0,20}:\/\/)[^\s\/?#@]{1,256}@/g, '$1[redacted]@')
  .replace(/\beyJ[A-Za-z0-9_-]{8,2000}\.[A-Za-z0-9_-]{8,2000}\.[A-Za-z0-9_-]{0,2000}/g, '[redacted]')
  .replace(/\b(?:AKIA|ASIA)[A-Z0-9]{12,32}\b/g, '[redacted]')
  .replace(/\b(?:sk|pk|rk|skr|ghp|gho|ghu|ghs|ghr|github_pat|glpat|xox[abeprs])[-_][A-Za-z0-9_-]{16,256}/g, '[redacted]')
  .replace(/[A-Fa-f0-9]{32,}/g, '[redacted]')
  .replace(/\b[A-Za-z0-9._%+-]{1,64}@[A-Za-z0-9-]{1,63}(?:\.[A-Za-z0-9-]{1,63}){1,8}\b/g, '[email]');
const cap = (value, max) => {
  const raw = points(String(value == null ? '' : value).slice(0, RAW * 2), RAW).join('');
  const kept = points(scrub(raw), max);
  return kept.length > max ? kept.slice(0, max - 3).join('') + '...' : kept.join('');
};
return {
  title: cap(String(input.input.title || '').trim(), 200).trim() || 'Untitled report',
  description: cap(input.input.description, 8000).trim() || 'No description',
  diagnostics: {},
  collection_complete: false,
